import {scenarioAllowsBackground} from './scenario-background-rules.js?v=surface-fill-1';
import {recordHazard} from './emergency-order.js?v=surface-fill-1';
import {beginEmergencySession} from './emergency-session.js?v=surface-fill-1';
const developed=t=>t.terrain==='land'&&['residential','commercial','industrial'].includes(t.type)&&t.level>0&&!t.rubble;
export const freshRiots=()=>({randomRiots:false,unrestMonths:0,riot:null,policeUnits:[],nextPolice:0,riots:0});
export function startRiot(c,x,y){const n=Math.sqrt(c.tiles.length),e=c.emergency;if(e.riot)return{ok:false,error:'This disaster type is already active.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n||!developed(c.tiles[y*n+x]))return{ok:false,error:'Choose an occupied residential, commercial or industrial building.'};beginEmergencySession(c);recordHazard(e,'riot');Object.assign(e,{riot:{x,y,age:0,anger:100}});e.riots++;return{ok:true};}
export function dispatchPolice(c,x,y){const e=c.emergency,n=Math.sqrt(c.tiles.length);if(!e.active)return{ok:false,error:'Police dispatch is available during an emergency.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n||c.tiles[y*n+x].terrain==='water')return{ok:false,error:'Dispatch police to land near the crowd.'};const limit=1+c.tiles.filter(t=>t.type==='police').length;e.policeUnits=e.policeUnits.slice(0,limit);if(e.policeUnits.length<limit)e.policeUnits.push({x,y});else{e.policeUnits[e.nextPolice%limit]={x,y};e.nextPolice=(e.nextPolice+1)%limit;}return{ok:true};}
export function stepRiot(c,ignite){const e=c.emergency,r=e.riot;if(!r)return;r.age++;const n=Math.sqrt(c.tiles.length),tile=c.tiles[r.y*n+r.x];e.policeUnits=e.policeUnits.slice(0,1+c.tiles.filter(t=>t.type==='police').length);let calm=2+(tile.policeCoverage||0)*.12;
 for(const [i,p] of e.policeUnits.entries()){const d=Math.hypot(p.x-r.x,p.y-r.y);if(d<=4){const funding=i===0?1:c.stats.strikes.includes('police')?0:c.civic.funding.police/100;calm+=18*(1-d/5)*funding*(i===0?1:.6+.4*c.stats.jailAdequacy);}}
 r.anger=Math.max(0,r.anger-calm);if(!r.anger||r.age>=40){e.riot=null;return;}
 if(r.age%3===0){const targets=c.tiles.filter(t=>developed(t)&&!t.fire&&Math.hypot(t.x-r.x,t.y-r.y)<=2);if(targets.length){const t=targets[(c.seed+r.age)%targets.length];ignite(c,t.x,t.y);}}
 if(r.age%2===0){const targets=c.tiles.filter(t=>developed(t)&&(t.x!==r.x||t.y!==r.y)&&Math.hypot(t.x-r.x,t.y-r.y)<=6);if(targets.length){const target=targets[(c.seed+r.age)%targets.length],dx=target.x-r.x,dy=target.y-r.y;const x=r.x+(Math.abs(dx)>=Math.abs(dy)?Math.sign(dx):0),y=r.y+(Math.abs(dx)<Math.abs(dy)?Math.sign(dy):0);if(c.tiles[y*n+x].terrain==='land'){r.x=x;r.y=y;}}}
}
export function validateRiots(v,n,version){if(version<33)return freshRiots();if(version>=34&&(typeof v.randomRiots!=='boolean'||!Number.isInteger(v.unrestMonths)||v.unrestMonths<0||v.unrestMonths>120000))throw Error('Invalid unrest settings.');const coord=p=>p&&Number.isInteger(p.x)&&Number.isInteger(p.y)&&p.x>=0&&p.y>=0&&p.x<n&&p.y<n;if(!Array.isArray(v.policeUnits)||v.policeUnits.length>n*n+1||!Number.isInteger(v.nextPolice)||v.nextPolice<0||v.nextPolice>n*n||!Number.isInteger(v.riots)||v.riots<0||v.riots>1e9)throw Error('Invalid riot data.');let riot=null;if(v.riot!==null){const r=v.riot;if(!coord(r)||!v.active||(version<96&&(v.tornado||v.earthquake||v.locust))||!v.riots||!Number.isInteger(r.age)||r.age<0||r.age>=40||!Number.isFinite(r.anger)||r.anger<=0||r.anger>100)throw Error('Invalid riot state.');riot={x:r.x,y:r.y,age:r.age,anger:r.anger};}if(!v.active&&v.policeUnits.length)throw Error('Police dispatch requires an emergency.');const policeUnits=v.policeUnits.map(p=>{if(!coord(p))throw Error('Invalid police dispatch.');return{x:p.x,y:p.y};});return{randomRiots:version>=34?v.randomRiots:false,unrestMonths:version>=34?v.unrestMonths:0,riot,policeUnits,nextPolice:v.nextPolice,riots:v.riots};}

export function unrestConditions(c){const s=c.stats,crime=Math.max(0,(s.averageCrime||0)-40),discontent=Math.max(0,40-(s.aura||0));return{sustained:!!s.population&&(crime>0||discontent>0),severity:Math.min(1,(crime+discontent)/60)};}
export function unrestRisk(c){const condition=unrestConditions(c);return c.emergency.randomRiots&&c.emergency.unrestMonths>=6&&condition.sustained?.03*condition.severity:0;}
export function setRandomRiots(c,value){if(c.emergency.active)return{ok:false,error:'Finish the active emergency before changing unrest settings.'};if(typeof value!=='boolean')return{ok:false,error:'Choose a valid unrest setting.'};if(value!==c.emergency.randomRiots)c.emergency.unrestMonths=0;c.emergency.randomRiots=value;return{ok:true};}
export function advanceUnrest(c){if(!scenarioAllowsBackground(c,'randomDisasters'))return false;const e=c.emergency;if(e.active)return false;const condition=unrestConditions(c);e.unrestMonths=e.randomRiots&&condition.sustained?Math.min(120000,e.unrestMonths+1):0;const risk=unrestRisk(c);if(!risk)return false;let n=Math.imul(c.month+823,374761393)^Math.imul(c.seed+41,668265263);n=Math.imul(n^(n>>>13),1274126177);if(((n^(n>>>16))>>>0)/4294967296>=risk)return false;const homes=c.tiles.filter(t=>developed(t)&&t.type==='residential').sort((a,b)=>(b.crime-b.aura)-(a.crime-a.aura));if(!homes.length)return false;const t=homes[0],r=startRiot(c,t.x,t.y);if(r.ok)e.unrestMonths=0;return r.ok;}
